package com.shadesofmorton.features;

import static com.shadesofmorton.testing.TestHelpers.clickObject;
import static com.shadesofmorton.testing.TestHelpers.setPlayerAnimation;
import static com.shadesofmorton.testing.TestHelpers.useItemOnObject;
import static net.runelite.api.MenuAction.GAME_OBJECT_FIRST_OPTION;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.shadesofmorton.PluginHarness;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * Posts spam-click sequences on the plugin's event bus and asserts the redundant click is
 * consumed. Exercises the real plugin: every feature is registered and receives the events.
 */
class PreventActionInterruptFeatureTest
{
	private static final int ACTION_ANIMATION = 832;
	private static final int PYRE_OBJECT_ID = ObjectID.TEMPLE_PYRE_LOGS;
	private static final int NON_PYRE_OBJECT_ID = 0;
	private static final int PYRE_TILE_X = 5;
	private static final int PYRE_TILE_Y = 6;

	private PluginHarness harness;

	@BeforeEach
	void setUp()
	{
		harness = new PluginHarness();
		harness.start();
	}

	private void assertSpamIsBlocked(MenuOptionClicked first, MenuOptionClicked second)
	{
		harness.post(first);
		assertFalse(first.isConsumed());

		setPlayerAnimation(harness.player, ACTION_ANIMATION);
		harness.post(second);
		assertTrue(second.isConsumed());
	}

	private void assertNeitherClickBlocked(MenuOptionClicked first, MenuOptionClicked second)
	{
		harness.post(first);
		setPlayerAnimation(harness.player, ACTION_ANIMATION);
		harness.post(second);

		assertFalse(first.isConsumed());
		assertFalse(second.isConsumed());
	}

	@ParameterizedTest
	@ValueSource(strings = { "Build", "Use", "Light" })
	void directObjectOptionSpam_isBlocked(String option)
	{
		assertSpamIsBlocked(
			clickObject(option, GAME_OBJECT_FIRST_OPTION, PYRE_OBJECT_ID, PYRE_TILE_X, PYRE_TILE_Y),
			clickObject(option, GAME_OBJECT_FIRST_OPTION, PYRE_OBJECT_ID, PYRE_TILE_X, PYRE_TILE_Y));
	}

	@ParameterizedTest
	@ValueSource(ints = { ItemID.LOGS_PYRE, ItemID.SHADE_BONES1 })
	void useFuelItemOnPyreSpam_isBlocked(int fuelItemId)
	{
		assertSpamIsBlocked(
			useItemOnObject(harness.client, PYRE_OBJECT_ID, fuelItemId),
			useItemOnObject(harness.client, PYRE_OBJECT_ID, fuelItemId));
	}

	@Test
	void useNonFuelItemOnPyre_isNotBlocked()
	{
		assertNeitherClickBlocked(
			useItemOnObject(harness.client, PYRE_OBJECT_ID, ItemID.HAMMER),
			useItemOnObject(harness.client, PYRE_OBJECT_ID, ItemID.HAMMER));
	}

	@Test
	void buildOnNonPyreObject_isNotBlocked()
	{
		assertNeitherClickBlocked(
			clickObject("Build", GAME_OBJECT_FIRST_OPTION, NON_PYRE_OBJECT_ID, PYRE_TILE_X, PYRE_TILE_Y),
			clickObject("Build", GAME_OBJECT_FIRST_OPTION, NON_PYRE_OBJECT_ID, PYRE_TILE_X, PYRE_TILE_Y));
	}

	@Test
	void nextStepAfterObjectAdvances_isNotBlocked()
	{
		// Add logs to an empty pyre.
		final MenuOptionClicked build =
			clickObject("Build", GAME_OBJECT_FIRST_OPTION, ObjectID.TEMPLE_PYRE, PYRE_TILE_X, PYRE_TILE_Y);
		harness.post(build);
		assertFalse(build.isConsumed());

		// Still animating, but the pyre has advanced to the logs stage — adding remains is allowed.
		setPlayerAnimation(harness.player, ACTION_ANIMATION);
		final MenuOptionClicked addRemains =
			clickObject("Use", GAME_OBJECT_FIRST_OPTION, ObjectID.TEMPLE_PYRE_LOGS, PYRE_TILE_X, PYRE_TILE_Y);
		harness.post(addRemains);
		assertFalse(addRemains.isConsumed());
	}
}

package com.shadesofmorton.features;

import static com.shadesofmorton.testing.TestHelpers.clickObject;
import static com.shadesofmorton.testing.TestHelpers.passTicks;
import static com.shadesofmorton.testing.TestHelpers.setPlayerAnimation;
import static com.shadesofmorton.testing.TestHelpers.setSanctity;
import static com.shadesofmorton.testing.TestHelpers.useItemOnObject;
import static com.shadesofmorton.testing.TestHelpers.worldView;
import static net.runelite.api.MenuAction.GAME_OBJECT_FIRST_OPTION;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;

import com.shadesofmorton.PluginHarness;
import java.util.stream.Stream;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.config.Notification;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * Posts whole repair / sanctify / sanctity flows on the plugin's event bus and asserts on the
 * notifications emitted. Exercises the real plugin with every feature registered.
 */
class TempleNotificationsFeatureTest
{
	private static final int ACTION_ANIMATION = 832;
	private static final int IDLE = -1;
	private static final int REPAIR_IDLE_TICKS = 2;
	private static final int SANCTIFY_IDLE_TICKS = 3;

	/**
	 * Any object id that is not the altar, standing in for a temple wall segment.
	 */
	private static final int WALL_OBJECT_ID = 0;

	private PluginHarness harness;

	@BeforeEach
	void setUp()
	{
		harness = new PluginHarness();
		harness.start();
	}

	private void assertStopsWith(MenuOptionClicked start, int idleTicks, Notification expected, String message)
	{
		harness.post(start);
		setPlayerAnimation(harness.player, ACTION_ANIMATION);
		passTicks(harness.eventBus, 1);
		setPlayerAnimation(harness.player, IDLE);
		passTicks(harness.eventBus, idleTicks);

		verify(harness.notifier).notify(expected, message);
	}

	private void assertNoNotification(MenuOptionClicked start)
	{
		harness.post(start);
		setPlayerAnimation(harness.player, ACTION_ANIMATION);
		passTicks(harness.eventBus, 1);
		setPlayerAnimation(harness.player, IDLE);
		passTicks(harness.eventBus, SANCTIFY_IDLE_TICKS);

		verify(harness.notifier, never()).notify(any(Notification.class), anyString());
	}

	static Stream<WorldPoint> repairTiles()
	{
		return Stream.of(
			new WorldPoint(3504, 3314, 0), new WorldPoint(3505, 3314, 0), new WorldPoint(3507, 3314, 0),
			new WorldPoint(3508, 3314, 0), new WorldPoint(3508, 3315, 0), new WorldPoint(3508, 3316, 0),
			new WorldPoint(3508, 3317, 0), new WorldPoint(3508, 3318, 0), new WorldPoint(3507, 3318, 0),
			new WorldPoint(3506, 3318, 0), new WorldPoint(3505, 3318, 0), new WorldPoint(3504, 3318, 0),
			new WorldPoint(3504, 3317, 0), new WorldPoint(3504, 3316, 0), new WorldPoint(3504, 3315, 0));
	}

	@ParameterizedTest
	@MethodSource("repairTiles")
	void repairingOnTile_thenStopping_notifies(WorldPoint tile)
	{
		worldView(harness.client, 0, 0, 0);

		assertStopsWith(
			clickObject("Reinforce", GAME_OBJECT_FIRST_OPTION, WALL_OBJECT_ID, tile.getX(), tile.getY()),
			REPAIR_IDLE_TICKS, harness.stoppedRepairingNotification, "Stopped repairing the temple.");
	}

	@Test
	void sanctifyingByLeftClickOnLitAltar_thenStopping_notifies()
	{
		assertStopsWith(
			clickObject("Use", GAME_OBJECT_FIRST_OPTION, ObjectID.TEMPLEFIRE_ALTAR, 0, 0),
			SANCTIFY_IDLE_TICKS, harness.stoppedSanctifyingNotification, "Stopped sanctifying oil.");
	}

	@ParameterizedTest
	@ValueSource(ints = { ItemID.OLIVEOIL1, ItemID.OLIVEOIL2, ItemID.OLIVEOIL3, ItemID.OLIVEOIL4 })
	void sanctifyingWithOilDoseOnLitAltar_thenStopping_notifies(int oilId)
	{
		assertStopsWith(
			useItemOnObject(harness.client, ObjectID.TEMPLEFIRE_ALTAR, oilId),
			SANCTIFY_IDLE_TICKS, harness.stoppedSanctifyingNotification, "Stopped sanctifying oil.");
	}

	@ParameterizedTest
	@ValueSource(ints = { ObjectID.TEMPLEFIRE_ALTAR_NOFIRE, ObjectID.TEMPLEFIRE_ALTAR_NOFIRE_BROKEN })
	void sanctifyingByLeftClickOnUnlitAltar_doesNotNotify(int altarId)
	{
		assertNoNotification(clickObject("Use", GAME_OBJECT_FIRST_OPTION, altarId, 0, 0));
	}

	@ParameterizedTest
	@ValueSource(ints = { ObjectID.TEMPLEFIRE_ALTAR_NOFIRE, ObjectID.TEMPLEFIRE_ALTAR_NOFIRE_BROKEN })
	void usingOilOnUnlitAltar_doesNotNotify(int altarId)
	{
		assertNoNotification(useItemOnObject(harness.client, altarId, ItemID.OLIVEOIL1));
	}

	@Test
	void sanctityReachingFull_notifies()
	{
		setSanctity(harness.eventBus, 100);

		verify(harness.notifier).notify(harness.fullSanctityNotification, "Temple at full sanctity.");
	}

	@Test
	void sanctityClimbingPastFull_notifiesOnlyOnce()
	{
		setSanctity(harness.eventBus, 100);
		setSanctity(harness.eventBus, 101);

		verify(harness.notifier, times(1)).notify(harness.fullSanctityNotification, "Temple at full sanctity.");
	}

	@Test
	void sanctityBelowFull_neverNotifies()
	{
		setSanctity(harness.eventBus, 99);

		verifyNoInteractions(harness.notifier);
	}

	@Test
	void sanctifying_withinIdleThreshold_doesNotNotifyYet()
	{
		harness.post(clickObject("Use", GAME_OBJECT_FIRST_OPTION, ObjectID.TEMPLEFIRE_ALTAR, 0, 0));

		setPlayerAnimation(harness.player, ACTION_ANIMATION);
		passTicks(harness.eventBus, 1);
		setPlayerAnimation(harness.player, IDLE);
		passTicks(harness.eventBus, 2);

		verify(harness.notifier, never()).notify(any(Notification.class), anyString());
	}

	@Test
	void clickingAwayMidAction_doesNotNotify()
	{
		harness.post(clickObject("Use", GAME_OBJECT_FIRST_OPTION, ObjectID.TEMPLEFIRE_ALTAR, 0, 0));
		setPlayerAnimation(harness.player, ACTION_ANIMATION);
		passTicks(harness.eventBus, 1);

		harness.post(clickObject("Walk here", MenuAction.WALK, 0, 0, 0));
		setPlayerAnimation(harness.player, IDLE);
		passTicks(harness.eventBus, 3);

		verifyNoInteractions(harness.notifier);
	}

	@Test
	void walkingToAction_doesNotNotifyBeforeItStarts_thenNotifiesAtEnd()
	{
		worldView(harness.client, 0, 0, 0);
		final WorldPoint tile = repairTiles().iterator().next();
		harness.post(clickObject("Reinforce", GAME_OBJECT_FIRST_OPTION, WALL_OBJECT_ID, tile.getX(), tile.getY()));

		setPlayerAnimation(harness.player, IDLE);
		passTicks(harness.eventBus, 3);

		verify(harness.notifier, never()).notify(any(Notification.class), anyString());

		setPlayerAnimation(harness.player, ACTION_ANIMATION);
		passTicks(harness.eventBus, 1);
		setPlayerAnimation(harness.player, IDLE);
		passTicks(harness.eventBus, 2);

		verify(harness.notifier).notify(harness.stoppedRepairingNotification, "Stopped repairing the temple.");
	}

	@Test
	void usingNonOilItemOnLitAltar_isNotTreatedAsSanctifying()
	{
		assertNoNotification(useItemOnObject(harness.client, ObjectID.TEMPLEFIRE_ALTAR, ItemID.HAMMER));
	}
}

package com.shadesofmorton.testing;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.EventBus;

/**
 * Builders for the real RuneLite events and API mocks that tests post on the plugin's event bus.
 * Events must be real instances (the EventBus dispatches by exact class), so only the backing
 * {@link MenuEntry} / API objects are mocked — never the event itself.
 */
public final class TestHelpers
{
	/** A menu click on a game object: option text, menu action, object id and scene x/y. */
	public static MenuOptionClicked clickObject(String option, MenuAction action, int id, int sceneX, int sceneY)
	{
		final MenuEntry entry = mock(MenuEntry.class);
		when(entry.getOption()).thenReturn(option);
		when(entry.getType()).thenReturn(action);
		when(entry.getIdentifier()).thenReturn(id);
		when(entry.getParam0()).thenReturn(sceneX);
		when(entry.getParam1()).thenReturn(sceneY);
		return new MenuOptionClicked(entry);
	}

	/** Using a selected inventory item on a game object (a "Use item -> object" interaction). */
	public static MenuOptionClicked useItemOnObject(Client client, int objectId, int selectedItemId)
	{
		final Widget selected = mock(Widget.class);
		when(selected.getItemId()).thenReturn(selectedItemId);
		when(client.getSelectedWidget()).thenReturn(selected);

		return clickObject("Use", MenuAction.WIDGET_TARGET_ON_GAME_OBJECT, objectId, 0, 0);
	}

	/** Sets the local player's animation for subsequent ticks (-1 = idle). Persists until changed. */
	public static void setPlayerAnimation(Player player, int animation)
	{
		when(player.getAnimation()).thenReturn(animation);
	}

	/** A VarbitChanged for a given var id and value (fires for VarPlayers too). */
	public static VarbitChanged varbitChanged(int varpId, int value)
	{
		final VarbitChanged event = new VarbitChanged();
		event.setVarpId(varpId);
		event.setValue(value);
		return event;
	}

	/** Stubs the client's top-level world view with the given base coords / plane, and returns it. */
	public static WorldView worldView(Client client, int baseX, int baseY, int plane)
	{
		final WorldView worldView = mock(WorldView.class);
		when(worldView.getBaseX()).thenReturn(baseX);
		when(worldView.getBaseY()).thenReturn(baseY);
		when(worldView.getPlane()).thenReturn(plane);
		when(client.getTopLevelWorldView()).thenReturn(worldView);
		return worldView;
	}

	/** Posts {@code count} game ticks on the bus. */
	public static void passTicks(EventBus eventBus, int count)
	{
		for (int i = 0; i < count; i++)
		{
			eventBus.post(new GameTick());
		}
	}

	/** Posts a temple-sanctity VarPlayer change on the bus. */
	public static void setSanctity(EventBus eventBus, int value)
	{
		eventBus.post(varbitChanged(VarPlayerID.TEMPLE_SANCTITY_P, value));
	}

	private TestHelpers()
	{
	}
}

package com.shadesofmorton;

