package com.shadesofmorton;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.Injector;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.Notification;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Builds the real {@link ShadesOfMortonPlugin} with mocked RuneLite APIs and a real
 * {@link EventBus}, so tests drive features the way the client does: register everything and
 * post events on the bus, rather than calling handlers directly.
 */
public final class PluginHarness
{
	public final EventBus eventBus = new EventBus();
	public final Client client = mock(Client.class);
	public final Notifier notifier = mock(Notifier.class);
	public final ShadesOfMortonConfig config = mock(ShadesOfMortonConfig.class);
	public final OverlayManager overlayManager = mock(OverlayManager.class);
	public final ClientThread clientThread = mock(ClientThread.class);
	public final ModelOutlineRenderer modelOutlineRenderer = mock(ModelOutlineRenderer.class);
	public final Player player = mock(Player.class);

	public final Notification fullSanctityNotification = new Notification();
	public final Notification stoppedRepairingNotification = new Notification();
	public final Notification stoppedSanctifyingNotification = new Notification();

	private final ShadesOfMortonPlugin plugin;

	public PluginHarness()
	{
		when(client.getLocalPlayer()).thenReturn(player);

		when(config.preventActionInterrupt()).thenReturn(true);
		when(config.pyreDespawnTimer()).thenReturn(true);
		when(config.chestPaths()).thenReturn(true);
		when(config.chestHighlight()).thenReturn(true);
		when(config.fullSanctityNotification()).thenReturn(fullSanctityNotification);
		when(config.stoppedRepairingNotification()).thenReturn(stoppedRepairingNotification);
		when(config.stoppedSanctifyingNotification()).thenReturn(stoppedSanctifyingNotification);

		final Injector injector = Guice.createInjector(new AbstractModule()
		{
			@Override
			protected void configure()
			{
				bind(EventBus.class).toInstance(eventBus);
				bind(Client.class).toInstance(client);
				bind(Notifier.class).toInstance(notifier);
				bind(ShadesOfMortonConfig.class).toInstance(config);
				bind(OverlayManager.class).toInstance(overlayManager);
				bind(ClientThread.class).toInstance(clientThread);
				bind(ModelOutlineRenderer.class).toInstance(modelOutlineRenderer);
			}
		});

		plugin = injector.getInstance(ShadesOfMortonPlugin.class);
	}

	/** Starts the plugin, registering every enabled feature on the event bus. */
	public void start()
	{
		plugin.startUp();
	}

	/** Posts an event on the bus, dispatching it to every registered feature. */
	public void post(Object event)
	{
		eventBus.post(event);
	}
}

package com.shadesofmorton;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/**
 * Single source of truth for detecting pyre interactions, so the interrupt and despawn-timer
 * features agree on what counts.
 */
public final class PyreInteractions
{
	/**
	 * @return true if this click adds fuel to a pyre: a "Build"/"Use" object option (adds pyre
	 * logs / remains from the inventory), or using a pyre-logs / shade-remains item on the pyre.
	 * Using an unrelated item on a pyre is ignored.
	 */
	public static boolean isAddInteraction(Client client, MenuOptionClicked event)
	{
		return matches(client, event, ShadesOfMortonConstants.PYRE_ADD_OPTIONS);
	}

	/**
	 * @return true if this click starts an interruptible pyre action: adding fuel (as
	 * {@link #isAddInteraction}) or lighting a completed pyre.
	 */
	public static boolean isPyreActionInteraction(Client client, MenuOptionClicked event)
	{
		return matches(client, event, ShadesOfMortonConstants.PYRE_ACTION_OPTIONS);
	}

	private static boolean matches(Client client, MenuOptionClicked event, Set<String> directOptions)
	{
		if (!ShadesOfMortonConstants.OBJECT_MENU_ACTIONS.contains(event.getMenuAction())
			|| !ShadesOfMortonConstants.PYRE_OBJECT_IDS.contains(event.getId()))
		{
			return false;
		}

		// Item-on-object — require the used item to be pyre logs or shade remains.
		if (event.getMenuAction() == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			final Widget selected = client.getSelectedWidget();
			return selected != null
				&& ShadesOfMortonConstants.PYRE_FUEL_ITEM_IDS.contains(selected.getItemId());
		}

		return directOptions.contains(Text.removeTags(event.getMenuOption()));
	}

	private PyreInteractions()
	{
	}
}

package com.shadesofmorton;

import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/**
 * Waypoint paths from the catacombs entrance to each metal's chest area. Each metal maps to
 * a list of <b>branches</b>; a branch is a polyline (corner waypoints, forward order
 * entrance → chest, plane 0) drawn as connected line segments. A single-destination route is
 * just one branch; a forked route has several (they repeat the shared prefix).
 */
public final class ShadeChestPaths
{
	/** Shared entrance tile — the start of every path. */
	private static final WorldPoint ENTRANCE = new WorldPoint(3493, 9726, 0);

	public static final Map<ShadeKeyMetal, List<List<WorldPoint>>> PATHS = Map.of(
		ShadeKeyMetal.BLACK, List.of(
			List.of(
				ENTRANCE,
				new WorldPoint(3493, 9716, 0),
				new WorldPoint(3493, 9708, 0),
				new WorldPoint(3488, 9705, 0),
				new WorldPoint(3488, 9699, 0),
				new WorldPoint(3485, 9696, 0),
				new WorldPoint(3479, 9696, 0),
				new WorldPoint(3479, 9692, 0)
			)
		),
		ShadeKeyMetal.BRONZE, List.of(
			// forks at (3493,9723) along y=9723
			List.of(ENTRANCE, new WorldPoint(3493, 9723, 0), new WorldPoint(3504, 9723, 0)), // east
			List.of(ENTRANCE, new WorldPoint(3493, 9723, 0), new WorldPoint(3482, 9723, 0))  // west
		),
		ShadeKeyMetal.SILVER, List.of(
			List.of(
				ENTRANCE,
				new WorldPoint(3493, 9715, 0),
				new WorldPoint(3493, 9708, 0),
				new WorldPoint(3467, 9708, 0)
			)
		),
		ShadeKeyMetal.STEEL, List.of(
			// common corridor to (3493,9708), then a west spur and an east spur along
			// y=9708, each with three chest stubs poking north to y=9710.
			// west spur
			List.of(ENTRANCE, new WorldPoint(3493, 9708, 0), new WorldPoint(3487, 9708, 0), new WorldPoint(3487, 9710, 0)),
			List.of(ENTRANCE, new WorldPoint(3493, 9708, 0), new WorldPoint(3479, 9708, 0), new WorldPoint(3479, 9710, 0)),
			List.of(ENTRANCE, new WorldPoint(3493, 9708, 0), new WorldPoint(3471, 9708, 0), new WorldPoint(3471, 9710, 0)),
			// east spur
			List.of(ENTRANCE, new WorldPoint(3493, 9708, 0), new WorldPoint(3499, 9708, 0), new WorldPoint(3499, 9710, 0)),
			List.of(ENTRANCE, new WorldPoint(3493, 9708, 0), new WorldPoint(3507, 9708, 0), new WorldPoint(3507, 9710, 0)),
			List.of(ENTRANCE, new WorldPoint(3493, 9708, 0), new WorldPoint(3515, 9708, 0), new WorldPoint(3515, 9710, 0))
		),
		ShadeKeyMetal.GOLD, List.of(
			List.of(
				ENTRANCE,
				new WorldPoint(3493, 9725, 0),
				new WorldPoint(3493, 9708, 0),
				new WorldPoint(3499, 9705, 0),
				new WorldPoint(3499, 9698, 0),
				new WorldPoint(3501, 9696, 0),
				new WorldPoint(3507, 9696, 0),
				new WorldPoint(3507, 9692, 0)
			)
		)
	);

	private ShadeChestPaths()
	{
	}
}

package com.shadesofmorton;

import com.google.inject.Provides;
import com.shadesofmorton.features.ChestHighlightFeature;
import com.shadesofmorton.features.ChestPathFeature;
import com.shadesofmorton.features.Feature;
import com.shadesofmorton.features.PreventActionInterruptFeature;
import com.shadesofmorton.features.PyreDespawnTimerFeature;
import com.shadesofmorton.features.TempleNotificationsFeature;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Shades of Mort'ton"
)
public class ShadesOfMortonPlugin extends Plugin
{
	@Inject
	private EventBus eventBus;

	@Inject
	private PreventActionInterruptFeature preventActionInterruptFeature;

	@Inject
	private PyreDespawnTimerFeature pyreDespawnTimerFeature;

	@Inject
	private ChestPathFeature chestPathFeature;

	@Inject
	private ChestHighlightFeature chestHighlightFeature;

	@Inject
	private TempleNotificationsFeature templeNotificationsFeature;

	private List<Feature> allFeatures;
	private final Set<Feature> activeFeatures = new HashSet<>();

	@Override
	protected void startUp()
	{
		allFeatures = List.of(preventActionInterruptFeature, pyreDespawnTimerFeature, chestPathFeature, chestHighlightFeature, templeNotificationsFeature);
		syncFeatures();
		log.debug("Shades of Mort'ton started");
	}

	@Override
	protected void shutDown()
	{
		for (Feature feature : activeFeatures)
		{
			eventBus.unregister(feature);
			feature.shutDown();
		}
		activeFeatures.clear();
		log.debug("Shades of Mort'ton stopped");
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ShadesOfMortonConfig.CONFIG_GROUP.equals(event.getGroup()))
		{
			syncFeatures();
		}
	}

	/**
	 * Register + start each enabled feature and unregister + stop each disabled one, so the
	 * set of active features matches the config toggles.
	 */
	private void syncFeatures()
	{
		for (Feature feature : allFeatures)
		{
			final boolean enabled = feature.isEnabled();
			final boolean active = activeFeatures.contains(feature);

			if (enabled && !active)
			{
				eventBus.register(feature);
				feature.startUp();
				activeFeatures.add(feature);
			}
			else if (!enabled && active)
			{
				eventBus.unregister(feature);
				feature.shutDown();
				activeFeatures.remove(feature);
			}
		}
	}

	@Provides
	ShadesOfMortonConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ShadesOfMortonConfig.class);
	}
}

package com.shadesofmorton.features;

import com.shadesofmorton.ShadesOfMortonConfig;
import com.shadesofmorton.ShadesOfMortonConstants;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Function;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.config.Notification;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

public class TempleNotificationsFeature implements Feature
{
	private static final int REPAIR_OR_SANCTIFY_ACTION_ANIMATION_ID = 832;

	private static final int FULL_SANCTITY = 100;

	private enum Activity
	{
		NONE(0, null),
		REPAIRING(2, "Stopped repairing the temple."),
		SANCTIFYING(3, "Stopped sanctifying oil.");

		/**
		 * Idle ticks beyond the inter-item animation gap before the action counts as stopped.
		 */
		final int numIdleTicksToNotify;
		final String idleNotificationMessage;

		Activity(int numIdleTicksToNotify, String idleNotificationMessage)
		{
			this.numIdleTicksToNotify = numIdleTicksToNotify;
			this.idleNotificationMessage = idleNotificationMessage;
		}
	}

	private static final Function<ShadesOfMortonConfig, Notification> NO_NOTIFICATION = config -> null;

	/**
	 * The config notification each activity fires when it stops. NONE is a no-op.
	 */
	private static final Map<Activity, Function<ShadesOfMortonConfig, Notification>> STOPPED_NOTIFICATIONS =
		new EnumMap<>(Map.of(
			Activity.NONE, NO_NOTIFICATION,
			Activity.REPAIRING, ShadesOfMortonConfig::stoppedRepairingNotification,
			Activity.SANCTIFYING, ShadesOfMortonConfig::stoppedSanctifyingNotification
		));

	static
	{
		for (Activity activity : Activity.values())
		{
			if (!STOPPED_NOTIFICATIONS.containsKey(activity))
			{
				// Can only happen if a developer adds an Activity without a handler above.
				throw new IllegalStateException("No stopped-notification handler for " + activity);
			}
		}
	}

	@Inject
	private Client client;

	@Inject
	private Notifier notifier;

	@Inject
	private ShadesOfMortonConfig config;

	/**
	 * The activity that the user is starting, but the player has not started the animation.
	 * This prevents us from notifying before the character actually started the action.
	 * For example when the player has clicked but the character is walking to the object.
	 */
	private Activity pendingActivity = Activity.NONE;

	/**
	 * The action that is in-progress, meaning the character is performing the animation.
	 */
	private Activity currentActivity = Activity.NONE;

	/**
	 * Num idle ticks since the current action last animated.
	 */
	private int numTicksSinceLastAction;

	private int lastSanctity = -1;

	@Override
	public void startUp()
	{
		resetState();
	}

	@Override
	public void shutDown()
	{
		resetState();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// Closing a right-click menu is not a redirect — ignore it.
		if (event.getMenuAction() == MenuAction.CANCEL)
		{
			return;
		}

		final Activity clicked = getActivityForEvent(event);
		if (clicked == pendingActivity)
		{
			return;
		}

		// A switch or interrupt drops the in-progress action silently; only a natural end notifies.
		pendingActivity = clicked;
		currentActivity = Activity.NONE;
		numTicksSinceLastAction = 0;
	}


	private Activity getActivityForEvent(MenuOptionClicked event)
	{
		if (!ShadesOfMortonConstants.OBJECT_MENU_ACTIONS.contains(event.getMenuAction()))
		{
			return Activity.NONE;
		}

		if (event.getId() == ShadesOfMortonConstants.SANCTIFY_ALTAR_OBJECT_ID && isSanctifyEvent(event))
		{
			return Activity.SANCTIFYING;
		}

		if ("Reinforce".equals(Text.removeTags(event.getMenuOption())) && isRepairTileClickEvent(event))
		{
			return Activity.REPAIRING;
		}

		return Activity.NONE;
	}

	private boolean isSanctifyEvent(MenuOptionClicked event)
	{
		// Use olive oil on the altar
		if (event.getMenuAction() == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			final Widget selected = client.getSelectedWidget();
			return selected != null
				&& ShadesOfMortonConstants.OLIVE_OIL_ITEM_IDS.contains(selected.getItemId());
		}

		// Left-click the altar (the text is just 'Use')
		return "Use".equals(Text.removeTags(event.getMenuOption()));
	}

	private boolean isRepairTileClickEvent(MenuOptionClicked event)
	{
		// param0/param1 are the scene X/Y of the clicked wall object.
		final WorldView worldView = client.getTopLevelWorldView();
		final WorldPoint tile = WorldPoint.fromScene(worldView, event.getParam0(), event.getParam1(), worldView.getPlane());
		return ShadesOfMortonConstants.TEMPLE_REPAIR_TILES.contains(tile);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		final Player local = client.getLocalPlayer();
		final boolean animating = local != null
			&& local.getAnimation() == REPAIR_OR_SANCTIFY_ACTION_ANIMATION_ID;

		if (animating)
		{
			if (pendingActivity != Activity.NONE)
			{
				currentActivity = pendingActivity;
				numTicksSinceLastAction = 0;
			}
			return;
		}

		// currentActivity stays NONE while walking to a clicked action, so that gap can't time out.
		if (currentActivity == Activity.NONE)
		{
			return;
		}

		numTicksSinceLastAction++;
		if (numTicksSinceLastAction >= currentActivity.numIdleTicksToNotify)
		{
			onActivityStopped();
		}
	}

	private void onActivityStopped()
	{
		final Notification notification = STOPPED_NOTIFICATIONS.get(currentActivity).apply(config);
		if (notification != null)
		{
			notifier.notify(notification, currentActivity.idleNotificationMessage);
		}

		pendingActivity = Activity.NONE;
		currentActivity = Activity.NONE;
		numTicksSinceLastAction = 0;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() != VarPlayerID.TEMPLE_SANCTITY_P)
		{
			return;
		}

		final int sanctity = event.getValue();

		// Sanctity can go above 100. Only notify when we go from under 100 to 100 or above.
		if (sanctity >= FULL_SANCTITY && lastSanctity < FULL_SANCTITY)
		{
			notifier.notify(config.fullSanctityNotification(), "Temple at full sanctity.");
		}

		lastSanctity = sanctity;
	}

	private void resetState()
	{
		pendingActivity = Activity.NONE;
		currentActivity = Activity.NONE;
		numTicksSinceLastAction = 0;
		lastSanctity = -1;
	}
}

package com.shadesofmorton.features;

import com.shadesofmorton.ShadeKey;
import com.shadesofmorton.ShadeKeyMetal;
import com.shadesofmorton.ShadesOfMortonConfig;
import java.util.EnumSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Shows a path from the catacombs entrance to the chest area for each key metal the player
 * is currently holding. Held metals are recomputed only when the inventory changes.
 */
public class ChestPathFeature implements Feature
{
	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ShadesOfMortonConfig config;

	private final Set<ShadeKeyMetal> heldMetals = EnumSet.noneOf(ShadeKeyMetal.class);

	private ChestPathOverlay overlay;

	@Override
	public void startUp()
	{
		overlay = new ChestPathOverlay(client, this);
		overlayManager.add(overlay);
		// getItemContainer must run on the client thread; startUp() does not.
		clientThread.invokeLater(this::recomputeHeldMetals);
	}

	@Override
	public void shutDown()
	{
		if (overlay != null)
		{
			overlayManager.remove(overlay);
			overlay = null;
		}
		heldMetals.clear();
	}

	@Override
	public boolean isEnabled()
	{
		return config.chestPaths();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			recomputeHeldMetals();
		}
	}

	Set<ShadeKeyMetal> getHeldMetals()
	{
		return heldMetals;
	}

	private void recomputeHeldMetals()
	{
		heldMetals.clear();

		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return;
		}

		for (Item item : inventory.getItems())
		{
			final ShadeKey key = ShadeKey.fromKeyItemId(item.getId());
			if (key != null)
			{
				heldMetals.add(key.getMetal());
			}
		}
	}
}

package com.shadesofmorton.features;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

/**
 * Renders the pyre despawn countdown as a pie over the tracked pyre. Turns red in the
 * final few seconds.
 */
class PyreDespawnTimerOverlay extends Overlay
{
	private static final int DIAMETER = 25;
	private static final double WARNING_THRESHOLD = 5d / 30d; // last ~5 seconds

	private final PyreDespawnTimerFeature feature;

	PyreDespawnTimerOverlay(PyreDespawnTimerFeature feature)
	{
		this.feature = feature;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final GameObject pyre = feature.getTrackedPyre();
		if (pyre == null)
		{
			return null;
		}

		final double remaining = feature.getRemainingFraction();
		if (remaining <= 0d)
		{
			return null;
		}

		final Point location = pyre.getCanvasLocation();
		if (location == null)
		{
			return null;
		}

		final Color fill = remaining <= WARNING_THRESHOLD ? Color.RED : Color.GREEN;

		final ProgressPieComponent pie = new ProgressPieComponent();
		pie.setPosition(location);
		pie.setDiameter(DIAMETER);
		pie.setProgress(remaining);
		pie.setFill(fill);
		pie.setBorderColor(fill);
		pie.render(graphics);

		return null;
	}
}

package com.shadesofmorton.features;

import com.shadesofmorton.ShadeKey;
import com.shadesofmorton.ShadesOfMortonConstants;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Glowing outline over each tracked chest whose key the player is holding, only while inside
 * the catacombs.
 */
class ChestHighlightOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 4;

	private final Client client;
	private final ChestHighlightFeature feature;
	private final ModelOutlineRenderer modelOutlineRenderer;

	ChestHighlightOverlay(Client client, ChestHighlightFeature feature, ModelOutlineRenderer modelOutlineRenderer)
	{
		this.client = client;
		this.feature = feature;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		final WorldPoint playerLocation = local.getWorldLocation();
		if (playerLocation == null || !ShadesOfMortonConstants.CATACOMBS_AREA.contains(playerLocation))
		{
			return null;
		}

		for (GameObject chest : feature.getChests())
		{
			final ShadeKey key = ShadeKey.fromChestObjectId(chest.getId());
			if (key != null && feature.getHeldKeys().contains(key))
			{
				modelOutlineRenderer.drawOutline(chest, OUTLINE_WIDTH, new Color(0, 255, 0), OUTLINE_FEATHER);
			}
		}

		return null;
	}
}

package com.shadesofmorton.features;

import com.shadesofmorton.PyreInteractions;
import com.shadesofmorton.ShadesOfMortonConfig;
import com.shadesofmorton.ShadesOfMortonConstants;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Draws a pie-style countdown over the local player's fueled pyre. A pyre holding logs or
 * shade remains despawns 30 seconds after it is built; adding more fuel resets the timer.
 */
public class PyreDespawnTimerFeature implements Feature
{
	static final Duration DESPAWN_TIME = Duration.ofSeconds(30);

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ShadesOfMortonConfig config;

	private final PyreDespawnTimerOverlay overlay = new PyreDespawnTimerOverlay(this);

	// Scene tile of the pyre the local player last interacted with ("mine").
	private int myPyreSceneX = -1;
	private int myPyreSceneY = -1;

	private GameObject trackedPyre;
	private Instant startTime;

	@Override
	public void startUp()
	{
		resetState();
		overlayManager.add(overlay);
	}

	@Override
	public void shutDown()
	{
		overlayManager.remove(overlay);
		resetState();
	}

	@Override
	public boolean isEnabled()
	{
		return config.pyreDespawnTimer();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (PyreInteractions.isAddInteraction(client, event))
		{
			// param0/param1 are the scene X/Y of the clicked object.
			myPyreSceneX = event.getParam0();
			myPyreSceneY = event.getParam1();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		final GameObject object = event.getGameObject();
		if (!ShadesOfMortonConstants.FUELED_PYRE_OBJECT_IDS.contains(object.getId()))
		{
			return;
		}

		final Point tile = object.getSceneMinLocation();
		if (tile.getX() == myPyreSceneX && tile.getY() == myPyreSceneY)
		{
			// Fuel added on the player's pyre — (re)start the countdown from full.
			trackedPyre = object;
			startTime = Instant.now();
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		if (event.getGameObject() == trackedPyre)
		{
			trackedPyre = null;
			startTime = null;
		}
	}

	GameObject getTrackedPyre()
	{
		return trackedPyre;
	}

	/**
	 * Fraction of the 30s window still remaining, clamped to [0, 1]. 0 when nothing tracked.
	 */
	double getRemainingFraction()
	{
		if (trackedPyre == null || startTime == null)
		{
			return 0d;
		}

		final double elapsed = Duration.between(startTime, Instant.now()).toMillis();
		final double fraction = 1d - elapsed / DESPAWN_TIME.toMillis();
		return Math.max(0d, Math.min(1d, fraction));
	}

	private void resetState()
	{
		trackedPyre = null;
		startTime = null;
		myPyreSceneX = -1;
		myPyreSceneY = -1;
	}
}

package com.shadesofmorton.features;

import com.shadesofmorton.PyreInteractions;
import com.shadesofmorton.ShadesOfMortonConfig;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.eventbus.Subscribe;

/**
 * Blocks redundant clicks on the burial site (funeral pyre) while the action is already in
 * progress, so spam-clicking doesn't keep restarting it.
 */
@Slf4j
public class PreventActionInterruptFeature implements Feature
{
	// Ticks to keep blocking after a valid click, covering the gap before the animation starts.
	private static final int COOLDOWN_TICKS = 2;

	@Inject
	private Client client;

	@Inject
	private ShadesOfMortonConfig config;

	private int blockUntilTick = -1;
	private int activeParam0 = -1;
	private int activeParam1 = -1;
	private int activeObjectId = -1;

	@Override
	public void startUp()
	{
		resetState();
	}

	@Override
	public void shutDown()
	{
		resetState();
	}

	@Override
	public boolean isEnabled()
	{
		return config.preventActionInterrupt();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		log.debug("menu click option='{}' target='{}' action={} id={} p0={} p1={}",
			event.getMenuOption(), event.getMenuTarget(), event.getMenuAction(),
			event.getId(), event.getParam0(), event.getParam1());

		if (!PyreInteractions.isPyreActionInteraction(client, event))
		{
			return;
		}

		final Player local = client.getLocalPlayer();
		final boolean isAnimating = local != null && local.getAnimation() != -1;
		final boolean cooling = client.getTickCount() < blockUntilTick;
		final boolean sameTile = event.getParam0() == activeParam0 && event.getParam1() == activeParam1;
		// The object id changes at each build step; a different id means the next step is ready.
		final boolean sameStep = event.getId() == activeObjectId;

		if ((isAnimating || cooling) && sameTile && sameStep)
		{
			// Redundant spam click on the step we're already working — block it so the
			// in-progress action isn't restarted.
			event.consume();
			return;
		}

		// First / allowed click: let it through and arm the cooldown against the spam that follows.
		blockUntilTick = client.getTickCount() + COOLDOWN_TICKS;
		activeParam0 = event.getParam0();
		activeParam1 = event.getParam1();
		activeObjectId = event.getId();
	}

	private void resetState()
	{
		blockUntilTick = -1;
		activeParam0 = -1;
		activeParam1 = -1;
		activeObjectId = -1;
	}
}

package com.shadesofmorton.features;

import com.shadesofmorton.ShadeChestPaths;
import com.shadesofmorton.ShadeKeyMetal;
import com.shadesofmorton.ShadesOfMortonConstants;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the polyline path(s) to the chest area for the metals the player is holding keys
 * for, but only while inside the catacombs.
 */
class ChestPathOverlay extends Overlay
{
	private final Client client;
	private final ChestPathFeature feature;

	ChestPathOverlay(Client client, ChestPathFeature feature)
	{
		this.client = client;
		this.feature = feature;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		final WorldPoint playerLocation = local.getWorldLocation();
		if (playerLocation == null || !ShadesOfMortonConstants.CATACOMBS_AREA.contains(playerLocation))
		{
			return null;
		}

		graphics.setStroke(new BasicStroke(2f));
		for (ShadeKeyMetal metal : feature.getHeldMetals())
		{
			final List<List<WorldPoint>> branches = ShadeChestPaths.PATHS.get(metal);
			if (branches == null)
			{
				continue;
			}
			final Color colour = metal.getColour();
			for (List<WorldPoint> branch : branches)
			{
				if (branch.size() >= 2)
				{
					drawPath(graphics, branch, colour);
				}
			}
		}

		return null;
	}

	private void drawPath(Graphics2D graphics, List<WorldPoint> path, Color colour)
	{
		graphics.setColor(colour);
		for (int i = 0; i < path.size() - 1; i++)
		{
			final Point from = toCanvas(path.get(i));
			final Point to = toCanvas(path.get(i + 1));
			if (from == null || to == null)
			{
				continue;
			}
			graphics.drawLine(from.getX(), from.getY(), to.getX(), to.getY());
		}
	}

	private Point toCanvas(WorldPoint worldPoint)
	{
		final LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
		if (localPoint == null)
		{
			return null;
		}
		return Perspective.localToCanvas(client, localPoint, worldPoint.getPlane());
	}
}

package com.shadesofmorton.features;

import com.shadesofmorton.ShadeKey;
import com.shadesofmorton.ShadesOfMortonConfig;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines the catacombs chests that match the keys the player is holding (exact metal +
 * colour). Held keys are recomputed only when the inventory changes; chest objects are
 * tracked via spawn/despawn.
 */
public class ChestHighlightFeature implements Feature
{
	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ShadesOfMortonConfig config;

	private final Set<ShadeKey> heldKeys = EnumSet.noneOf(ShadeKey.class);
	private final Set<GameObject> chests = new HashSet<>();

	private ChestHighlightOverlay overlay;

	@Override
	public void startUp()
	{
		overlay = new ChestHighlightOverlay(client, this, modelOutlineRenderer);
		overlayManager.add(overlay);
		// getItemContainer must run on the client thread; startUp() does not.
		clientThread.invokeLater(this::recomputeHeldKeys);
	}

	@Override
	public void shutDown()
	{
		if (overlay != null)
		{
			overlayManager.remove(overlay);
			overlay = null;
		}
		heldKeys.clear();
		chests.clear();
	}

	@Override
	public boolean isEnabled()
	{
		return config.chestHighlight();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			recomputeHeldKeys();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		final GameObject object = event.getGameObject();
		if (ShadeKey.fromChestObjectId(object.getId()) != null)
		{
			chests.add(object);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		chests.remove(event.getGameObject());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// A scene reload clears objects without always firing GameObjectDespawned; drop the
		// stale references so nothing is outlined after leaving.
		if (event.getGameState() == GameState.LOADING)
		{
			chests.clear();
		}
	}

	Set<GameObject> getChests()
	{
		return chests;
	}

	Set<ShadeKey> getHeldKeys()
	{
		return heldKeys;
	}

	private void recomputeHeldKeys()
	{
		heldKeys.clear();

		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return;
		}

		for (Item item : inventory.getItems())
		{
			final ShadeKey key = ShadeKey.fromKeyItemId(item.getId());
			if (key != null)
			{
				heldKeys.add(key);
			}
		}
	}
}

package com.shadesofmorton.features;

/**
 * A self-contained unit of plugin behavior. Each feature owns its own {@code @Subscribe}
 * handlers and state; the main plugin registers/unregisters it on the event bus and drives
 * this lifecycle.
 */
public interface Feature
{
	void startUp();

	void shutDown();

	/**
	 * Whether this feature is currently enabled (from its own injected config). The plugin
	 * registers/unregisters the feature to match. Defaults to always on.
	 */
	default boolean isEnabled()
	{
		return true;
	}
}

